export GLM_API_KEY='在這裡貼上你的 Coding Plan API Key' && CONFIG="$HOME/.hermes/config.yaml" && BAK="$HOME/.hermes/config.yaml.bak.coding-plan-$(date +%Y%m%d-%H%M%S)" && cp "$CONFIG" "$BAK" && sed -i.bak 's/^  provider: zai$/  provider: custom:zai-coding/' "$CONFIG" && if ! grep -q "^custom_providers:" "$CONFIG"; then printf '\ncustom_providers:\n  - api_key_env: GLM_API_KEY\n    base_url: https://api.z.ai/api/coding/paas/v4\n    default_model: glm-5.2\n    format: openai\n    name: zai-coding\n    key_env: GLM_API_KEY\n' >> "$CONFIG"; fi && echo "✅ 切換完成！備份：$BAK" && echo "現在重啟 Hermes（或關掉再開新對話）。"
